package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class CourseApiTest {
 StudyApiTest f;CourseStore store;CourseController api;
 @BeforeEach void setup(){f=new StudyApiTest();f.setup();store=mock(CourseStore.class);api=new CourseController(store,f.api,new SimpleMeterRegistry());}
 MockHttpServletRequest req(String method,String body){var r=f.req(method,body);r.removeHeader("If-Match");r.addHeader("If-Match","\"co1\"");return r;}
 CourseStore.Course value(){return new CourseStore.Course(f.id,f.group,f.space,f.actor,1,"Course","Purpose","DRAFT","PRIVATE",List.of(),Instant.now().toString(),Instant.now().toString());}
 @Test void ownerCreatesWithFreshAuthorityAndOwnCourseTag()throws Exception{when(store.create(eq(f.group),eq(f.space),eq(f.actor),anyString(),eq("Study"),eq("Purpose"),anyString())).thenReturn(new CourseStore.Result(value(),true));var v=api.create(f.group.toString(),req("POST",f.settings()));assertEquals(201,v.getStatusCode().value());assertEquals("\"co1\"",v.getHeaders().getETag());assertEquals("no-store",v.getHeaders().getCacheControl());assertTrue(v.getHeaders().getLocation().toString().endsWith("/courses/"+f.id));}
 @Test void memberAndViewerReadButAllCourseMutationsRequireOwner()throws Exception{for(String role:List.of("MEMBER","VIEWER")){f.role(role);when(store.get(f.group,f.space,f.id)).thenReturn(value());assertEquals(200,api.get(f.group.toString(),f.id.toString(),req("GET",null)).getStatusCode().value());assertEquals(403,assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),req("POST",f.settings()))).getStatusCode().value());assertThrows(ResponseStatusException.class,()->api.curriculum(f.group.toString(),f.id.toString(),req("PUT","{\"studyIds\":[]}")));assertThrows(ResponseStatusException.class,()->api.retire(f.group.toString(),f.id.toString(),req("DELETE",null)));}verify(store,times(2)).get(f.group,f.space,f.id);verifyNoMoreInteractions(store);}
 @Test void originCookieAndRevokedGrantBlockBeforeStore(){var a=req("POST",f.settings());a.setSecure(false);var b=req("POST",f.settings());b.addHeader("Cookie","__Host-brain_guest="+f.token);var c=req("POST",f.settings());c.addHeader("Origin","https://elsewhere.example");for(var v:List.of(a,b,c))assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),v));verifyNoInteractions(f.auth,store);when(f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.actor,"REGISTERED",List.of()));assertThrows(ResponseStatusException.class,()->api.get(f.group.toString(),f.id.toString(),req("GET",null)));verifyNoInteractions(store);}
 @Test void exactCurriculumJsonAndStrongEtagsRejectSpoofing(){for(String text:List.of("{}","{\"studyIds\":null}","{\"studyIds\":[],\"spaceId\":\"spoof\"}","{\"studyIds\":[],\"studyIds\":[]}","{\"studyIds\":[]} {}","{\"studyIds\":[\""+f.id+"\",\""+f.id+"\"]}"))assertThrows(ResponseStatusException.class,()->api.curriculum(f.group.toString(),f.id.toString(),req("PUT",text)));var missing=req("DELETE",null);missing.removeHeader("If-Match");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.retire(f.group.toString(),f.id.toString(),missing)).getStatusCode().value());for(String tag:List.of("*","W/\"co1\"","\"st1\"","\"co0\"","\"co9999999999999999999\"")){var v=req("DELETE",null);v.removeHeader("If-Match");v.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.retire(f.group.toString(),f.id.toString(),v));}verifyNoInteractions(store);}
 @Test void boundedHistoryAndEmptyReadsAndKeysAreStrict(){var read=req("GET","{}");assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),read));var history=req("GET",null);history.addParameter("limit","6");assertThrows(ResponseStatusException.class,()->api.history(f.group.toString(),f.id.toString(),history));var query=req("GET",null);query.addParameter("actorId",f.actor.toString());assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),query));var key=req("POST",f.settings());key.addHeader("Idempotency-Key","b".repeat(32));assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),key));var large=req("POST","x".repeat(65537));assertEquals(413,assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),large)).getStatusCode().value());verifyNoInteractions(store);}
}
